from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(3, 8))
    # values in [1, N]; small range to create many duplicates and equal runs
    mode = draw(st.integers(0, 3))
    if mode == 0:
        a = draw(st.lists(st.integers(1, n), min_size=n, max_size=n))
    elif mode == 1:
        v = draw(st.integers(1, n))
        a = [v] * n
    elif mode == 2:
        a = list(range(1, n + 1))
    else:
        k = draw(st.integers(1, min(3, n)))
        a = draw(st.lists(st.integers(1, k), min_size=n, max_size=n))
    return f"{n}\n{' '.join(map(str, a))}\n"

def validate(inp):
    t = inp.split()
    if len(t) < 1:
        return False
    n = int(t[0])
    if not (3 <= n <= 3 * 10**5):
        return False
    if len(t) != n + 1:
        return False
    a = [int(x) for x in t[1:]]
    return all(1 <= x <= n for x in a)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    a = [int(x) for x in t[1:1 + n]]
    cnt = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if a[i] == a[k] and a[i] != a[j]:
                    cnt += 1
    return str(cnt)
